.form-field__input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}
.form-field__input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(217,48,37,.15);
}

.form-field__help {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-top: .125rem;
}

.form-field__error {
  font-size: .8125rem;
  color: var(--color-error-text);
  font-weight: 500;
  margin-top: .125rem;
}
.form-field__error:not([hidden]) { display: block; }

