   Submit button
   ============================================= */
.form-actions { margin-top: .5rem; }

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .75rem 1.75rem;
  font-family: var(--font);
  font-size: .9375rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
