  max-width: 900px;
  margin: 0 auto;
  padding: .875rem 1.5rem;
  display: flex;
  align-items: center;
  gap: .6rem;
}
.site-header__logo { font-size: 1.4rem; }
.site-header__brand { font-weight: 600; font-size: 1.05rem; letter-spacing: -.01em; }

