  margin-top: .125rem;
}

.form-field__error {
  font-size: .8125rem;
  color: var(--color-error-text);
  font-weight: 500;
  margin-top: .125rem;
}
.form-field__error:not([hidden]) { display: block; }

/* =============================================
   Submit button
   ============================================= */
.form-actions { margin-top: .5rem; }

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .75rem 1.75rem;
  font-family: var(--font);
  font-size: .9375rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-sm);
