  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* =============================================
   Reduced motion
   ============================================= */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; }
