 * Contact Support Form — validation & submission logic
 *
 * Validation rules:
 *   - Full name: required, non-empty after trimming
 *   - Email:     required, valid RFC-ish format
 *   - Phone:     optional; when provided must match international/domestic pattern
 *
 * Accessibility contract (WCAG 2.2 AA):
 *   - aria-invalid / aria-describedby kept in sync with error state
 *   - On submit error: focus moves to first invalid field
 *   - Success announced via role="status"; errors via role="alert" summary
 *   - Inline error regions use hidden attribute (not display:none) to preserve
 *     the aria-describedby reference without exposing empty nodes to AT
 */

(function () {
  'use strict';

  /* ── Field descriptors ────────────────────────────────────────────── */
  const FIELDS = [
    {
      id: 'full-name',
      errorId: 'full-name-error',
      validate(value) {
        if (!value.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    {
      id: 'email',
      errorId: 'email-error',
      validate(value) {
        if (!value.trim()) return 'Error: Email address is required.';
        /* Simple but robust enough for client-side feedback */
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim())) {
          return 'Error: Enter a valid email address, e.g. name@example.com.';
        }
        return null;
      },
    },
    {
      id: 'phone',
      errorId: 'phone-error',
      validate(value) {
        if (!value.trim()) return null; /* optional */
        /*
         * Accepts:
         *   +1 555 000 1234  (international with spaces)
         *   +15550001234     (international no spaces)
         *   555-000-1234     (domestic with dashes)
         *   (555) 000-1234   (US style)
         *   5550001234       (digits only, 7–15 digits)
         */
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim())) {
          return 'Error: Enter a valid phone number, e.g. +1 555 000 1234.';
        }
        return null;
      },
    },
  ];

  /* ── DOM refs ─────────────────────────────────────────────────────── */
  const form          = document.getElementById('contact-form');
  const errorSummary  = document.getElementById('form-errors-summary');
  const successMsg    = document.getElementById('form-success');

  /* ── Helpers ──────────────────────────────────────────────────────── */
  function getInput(fieldId)      { return document.getElementById(fieldId); }
  function getErrorEl(errorId)    { return document.getElementById(errorId); }

  /** Mark a field valid: clear aria-invalid and hide error paragraph */
  function clearError(field) {
    const input = getInput(field.id);
    const errorEl = getErrorEl(field.errorId);

    input.removeAttribute('aria-invalid');
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  /** Mark a field invalid: set aria-invalid and surface error text */
  function showError(field, message) {
    const input = getInput(field.id);
    const errorEl = getErrorEl(field.errorId);

    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = message;
    errorEl.hidden = false;
  }

  /** Validate one field descriptor; returns error string or null */
  function validateField(field) {
    const input = getInput(field.id);
    return field.validate(input.value);
  }

  /** Hide the banner regions */
  function clearBanners() {
    errorSummary.hidden = true;
    errorSummary.textContent = '';
    successMsg.hidden = true;
    successMsg.textContent = '';
  }

  /* ── Blur-time (on-leave) validation ─────────────────────────────── */
  FIELDS.forEach(function (field) {
    const input = getInput(field.id);
    if (!input) return;

    input.addEventListener('blur', function () {
      const error = validateField(field);
      if (error) {
        showError(field, error);
      } else {
        clearError(field);
      }
    });

    /* Clear error as soon as the user starts correcting */
    input.addEventListener('input', function () {
      if (input.getAttribute('aria-invalid') === 'true') {
        const error = validateField(field);
        if (!error) clearError(field);
      }
    });
  });

  /* ── Submit handler ───────────────────────────────────────────────── */
  form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearBanners();

    const errors = [];

    FIELDS.forEach(function (field) {
      const error = validateField(field);
      if (error) {
        showError(field, error);
        errors.push({ field, message: error });
      } else {
        clearError(field);
      }
    });

    if (errors.length > 0) {
      /* Announce summary via the pre-existing role="alert" region */
      const noun = errors.length === 1 ? 'error' : 'errors';
      errorSummary.textContent =
        errors.length + ' ' + noun + ' prevented your message from being sent. ' +
        'Please review the fields below.';
      errorSummary.hidden = false;

      /* Move focus to the first invalid field so keyboard / SR users land there */
      getInput(errors[0].field.id).focus();
      return;
    }

    /* Simulate successful submission */
    form.reset();
    FIELDS.forEach(clearError);
    successMsg.textContent =
      'Your message has been sent. We\u2019ll be in touch within one business day.';
    successMsg.hidden = false;
  });
})();
